**React skeleton for the Curator approval carousel**
```tsx
import {useState, useEffect} from 'react';

interface Annotation {
  id: string;
  text: string;
  author: string;
  status: 'pending' | 'approved' | 'rejected';
}

const CuratorFlow = () => {
  const [queue, setQueue] = useState<Annotation[]>([]);
  const [current, setCurrent] = useState<Annotation | null>(null);
  const [comment, setComment] = useState('');

  useEffect(() => {
    // fetch pending annotations once
    fetch('/api/annotations?status=pending')
      .then(r => r.json())
      .then(setQueue);
  }, []);

  const openNext = () => {
    const next = queue[0];
    if (next) {
      setCurrent(next);
    }
  };

  const vote = (decision: 'approve' | 'reject' | 'edit') => {
    if (!current) return;
    fetch(`/api/annotations/${current.id}/vote`, {
      method: 'POST',
      body: JSON.stringify({decision, comment}),
      headers: {'Content-Type': 'application/json'}
    })
      .then(() => {
        setQueue(queue.filter(a => a.id !== current.id));
        setCurrent(null);
        setComment('');
        if (queue.length > 1) openNext();
      });
  };

  return (
    <div className="carousel">
      <div className="queue">{queue.map(a => (<div key={a.id} className="card">{a.text} - {a.author}<button onClick={() => {setCurrent(a);}}>Review</button></div>))}</div>
      {current && (
        <div className="panel">
          <h3>Review: {current.text}</h3>
          <textarea value={comment} onChange={e=>setComment(e.target.value)} placeholder="Add notes…"/>
          <button onClick={()=>vote('approve')}>Approve</button>
          <button onClick={()=>vote('reject')}>Reject</button>
          <button onClick={()=>vote('edit')}>Request Edit</button>
        </div>)}
      {queue.length === 0 && <p>All annotations processed.</p>}
    </div>
  );
};
```
*Key points*: 
- The carousel loads the queue once and keeps it in memory, so the UI stays responsive. 
- The `vote` API endpoint should atomically set the annotation’s status and log the curator’s decision, potentially triggering a lightweight approval workflow (composite flag → aggregate vote). 
- If the curator reaches *Request Edit*, we could push the annotation back to the *author*’s draft queue with a comment.

