  annotationId: string;
  decision: 'Approve' | 'Reject' | 'Edit';
  comment?: string;
  instantMerge?: boolean;
}

export interface VoteResponse {
  vote: {
    id: string;
    decision: string;
    instantMerge: boolean;
    comment: string;
    updatedAt: string;
  };
}

export interface BulkPublishResponse {
  bulkPublish: {
