import { useMutation } from '@apollo/client';
import { VOTE_MUTATION } from './gql';
import type { VoteInput, VoteResponse } from './types';

export const ActionPane = ({ id }: { id: string }) => {
  const [vote] = useMutation<VoteResponse, { input: VoteInput }>(VOTE_MUTATION);

  const onSubmit = async (data: VoteInput) => {
    try {
      const { data: res } = await vote({ variables: { input: data } });
      console.log('Vote result', res?.vote);
      // trigger a refetch of the queue if needed
    } catch (e) {
      console.error('Vote error', e);
    }
  };

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        const form = e.target as HTMLFormElement;
        const decision = (form.elements.namedItem('decision') as HTMLSelectElement).value as VoteInput['decision'];
        const comment = (form.elements.namedItem('comment') as HTMLInputElement).value;
        const instantMerge = (form.elements.namedItem('instantMerge') as HTMLInputElement).checked;
        onSubmit({ annotationId: id, decision, comment, instantMerge });
      }}
    >
      <select name="decision">
        <option value="Approve">Approve</option>
        <option value="Reject">Reject</option>
        <option value="Edit">Request Edit</option>
      </select>
      <input type="text" name="comment" placeholder="Comment" />
      <label>
        <input type="checkbox" name="instantMerge" /> Merge suggestion now
      </label>
      <button type="submit">Submit</button>
    </form>
  );
};

